import{_ as r,o,c as n,ag as l}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"知识库是什么（入门）","description":"","frontmatter":{},"headers":[],"relativePath":"AI/knowledge-base.md","filePath":"AI/knowledge-base.md"}'),e={name:"AI/knowledge-base.md"};function s(a,t,g,i,d,h){return o(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="知识库是什么-入门" tabindex="-1">知识库是什么（入门） <a class="header-anchor" href="#知识库是什么-入门" aria-label="Permalink to &quot;知识库是什么（入门）&quot;">​</a></h1><p>大模型的参数里装着训练时见过的世界，但<strong>不会自动知道</strong>你们公司的接口约定、上周刚改的业务规则，或某份只在内网 Wiki 里的排障手册。<strong>知识库</strong>要解决的，就是：在回答或行动之前，先从一批<strong>外部资料</strong>里找出相关片段，再交给模型用。</p><p>可以粗记成：</p><blockquote><p><strong>模型 = 脑子；知识库 = 可检索的参考书架。</strong></p></blockquote><p>行业里常把「先检索、再生成」这条路径叫 <strong>RAG</strong>（Retrieval-Augmented Generation）。入门阶段先抓住「补外部资料」即可，不必一上来抠向量库怎么建。</p><p>相关概念：<a href="./agent.html">Agent</a>、<a href="./skill.html">Skill</a>、<a href="./mcp.html">MCP</a>；四者怎么选见：<a href="./skill-vs-mcp.html">Skill、MCP、Rule 异同</a>。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>没有知识库时，常见凑合办法：</p><table tabindex="0"><thead><tr><th>做法</th><th>长处</th><th>短处</th></tr></thead><tbody><tr><td><strong>全塞进 Prompt / 系统提示</strong></td><td>实现简单</td><td>一长就爆上下文；每轮都带着，贵且吵</td></tr><tr><td><strong>微调（Fine-tune）</strong></td><td>把风格/格式「焊进」模型</td><td>贵、慢；事实一变就要再训；不适合天天变的业务文档</td></tr><tr><td><strong>指望模型「自己记得」</strong></td><td>零工程</td><td>私有知识根本不在训练集里；还容易一本正经瞎编</td></tr></tbody></table><p>知识库更适合：</p><ul><li><strong>私有文档</strong>：PRD、接口文档、oncall 手册、合同条款摘要</li><li><strong>会变的事实</strong>：上线说明、配置说明、组织内名词表</li><li><strong>需要可追溯</strong>：回答最好能指回「出自哪段资料」</li></ul><p>一句话：<strong>把「该知道的事实」放在模型外面，用的时候再捞进来。</strong></p><h2 id="和-agent、skill、mcp-怎么分工" tabindex="-1">和 Agent、Skill、MCP 怎么分工 <a class="header-anchor" href="#和-agent、skill、mcp-怎么分工" aria-label="Permalink to &quot;和 Agent、Skill、MCP 怎么分工&quot;">​</a></h2><p>这几个词经常一起出现，但不是互相替代：</p><table tabindex="0"><thead><tr><th>概念</th><th>一句话</th><th>典型形态</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td><strong>谁</strong>在多步完成任务</td><td>Cursor Agent、Claude Code 等运行时</td></tr><tr><td><strong>知识库</strong></td><td>任务相关的<strong>资料从哪来</strong></td><td>文档库、仓库索引、产品里的「知识库」</td></tr><tr><td><strong>Skill</strong></td><td>这类任务<strong>按什么步骤做</strong></td><td><code>SKILL.md</code> 流程与清单</td></tr><tr><td><strong>MCP</strong></td><td><strong>怎么连</strong>外部系统（查库、调 API、读远端资源）</td><td>MCP Server + Tools / Resources</td></tr></tbody></table><p>关系可以记成：</p><ul><li>Agent 是<strong>执行者</strong></li><li>知识库是<strong>参考资料</strong>（偏只读上下文）</li><li>Skill 是<strong>怎么干</strong>（流程）</li><li>MCP 是<strong>手脚怎么伸出去</strong>（协议与工具）</li></ul><p>举例：用户说「按我们组的事故定级，查一下昨晚那个超时」。</p><ul><li><strong>知识库</strong>：事故定级标准、历史类似 case 的说明</li><li><strong>Skill</strong>：收集时间线 → 查日志 → 定级 → 输出影响面与止血</li><li><strong>MCP</strong>（或其它工具）：去 Sentry / 日志平台拉真实事件</li><li><strong>Agent</strong>：按 Skill 编排，必要时检索知识库、调用 MCP，再给出结论</li></ul><p>只有知识库：资料在，但没人按流程查线上、也没人整理结论。只有 Skill：步骤清楚，但定级标准可能过时或不在仓库里。只有 MCP：能拉原始 JSON，不一定知道你们怎么定级。</p><h2 id="日常常见形态" tabindex="-1">日常常见形态 <a class="header-anchor" href="#日常常见形态" aria-label="Permalink to &quot;日常常见形态&quot;">​</a></h2><p>产品名字五花八门，形态往往类似：</p><ol><li><strong>文档型知识库</strong>：上传 PDF / Markdown / 网页，问答时检索片段（客服 Bot、内部助手常见）</li><li><strong>代码 / 仓库索引</strong>：IDE 或 Agent 对当前工程建索引，改代码时先搜相关文件（偏「工程上下文」，也常被叫作知识/记忆能力）</li><li><strong>通过工具读资料</strong>：知识不一定在专用「库」里——也可能是 MCP Resource、Wiki API、Confluence 搜索；对 Agent 来说，仍是「先拿到相关文本再回答」</li></ol><p>入门时不必纠结品牌名：问自己两件事——<strong>资料存在哪</strong>，以及<strong>回答前有没有把相关片段捞进上下文</strong>。</p><h2 id="边界与注意" tabindex="-1">边界与注意 <a class="header-anchor" href="#边界与注意" aria-label="Permalink to &quot;边界与注意&quot;">​</a></h2><p>知识库不是万能记忆：</p><ul><li><strong>检索错 → 答错</strong>：捞到无关或过期片段，模型会一本正经用错材料</li><li><strong>不是训练替代品</strong>：它补的是「当前要用的上下文」，不会永久改写模型权重</li><li><strong>权限与敏感信息</strong>：合同、密钥、个人信息进库前要想清楚谁能检索、日志里是否落盘</li><li><strong>和长上下文的取舍</strong>：窗口够大时可以多塞一点原文；资料很多、很杂时，仍需要检索，而不是整库粘贴</li></ul><p>落地时优先保证：<strong>资料够新、分段合理、问答能回溯来源</strong>。向量怎么切、要不要重排，是下一层的工程题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>知识库</strong> = 模型外面的可检索资料，用来减少瞎编、补私有与过时知识</li><li>和 <strong>Agent / Skill / MCP</strong> 正交：资料、流程、连接、执行者各管一截</li><li>入门先分清「要不要外部资料」；RAG 管道怎么搭，后面再专题写</li></ul>',30)])])}const u=r(e,[["render",s]]);export{c as __pageData,u as default};
